/* Player actions use simulation months rather than integer-age cooldowns. */
(function(root){
'use strict';
const now=()=>S.age*12+Math.floor((S.t||0)*12+1e-6),jobs=new Set(['jobhunt','workback','workagain','dreamjob']),moves=new Set(['moveout','movehome','moveplan','bigger','smaller']),trips=new Set(['trip','abroad','hometrip','visittrip']);
const stages={cook:['Основы кухни','Тесто и выпечка','Кремы и десерты','Сложные техники','Авторское меню'],engineer:['Техническая база','Прикладные расчёты','Проектирование','Сложные системы','Ведение проектов'],driver:['Безопасное вождение','Планирование маршрутов','Экономичное вождение','Сложные перевозки','Наставник водителей'],teacher:['Методика обучения','Планирование занятий','Работа с группой','Сложные учебные случаи','Авторская программа'],doctor:['Клиническая база','Диагностика','Ведение пациентов','Сложные случаи','Практика наставника'],general:['Основы специальности','Уверенная практика','Продвинутые приёмы','Сложные задачи','Мастерство и наставничество']};
function state(){if(!S.lifelineSchedule)S.lifelineSchedule={last:{},levels:{},meet:[],leave:Math.min(24,Math.max(0,S.jobY||0)*12),at:now(),autoParents:false,nextParents:null,school:null};return S.lifelineSchedule;}
function specialty(){return !['none','seeking','student','homemaker','retired'].includes(S.job)&&S.job?S.job:S.major||'general';}
function stage(){const s=state(),key=specialty(),level=s.levels[key]||0;return {key,level,title:(stages[key]||stages.general)[Math.min(level,4)]};}
function group(id){return jobs.has(id)||id.startsWith('transport-job-')?'job':moves.has(id)||id==='own_house'?'move':id==='remodel'?'remodel':id==='willwrite'?'will':null;}
function reason(id){const s=state(),base=id.split('@')[0],g=group(base),months=g==='job'||g==='will'?6:12,left=g?s.last[g]+months-now():0;if(left>0)return 'Снова доступно через '+Math.ceil(left)+' мес.';if(trips.has(base)){if((s.tripUntil||0)>now())return 'Вы ещё не вернулись из поездки';const need=base==='trip'?6:10;if(isWorking()&&s.leave<need)return 'Нет дней отпуска · накоплено '+Math.floor(s.leave)+' из '+need;}if(base==='meet'){const recent=s.meet.filter(m=>now()-m<3);if(recent.length>=4)return 'Пока вариантов больше нет, попробуйте позже · через '+Math.max(1,3-(now()-recent[0]))+' мес.';}if(base==='course'&&id.endsWith('@c')&&stage().level>=5)return 'Все 5 ступеней этой специальности уже пройдены';if(['kidpub','kidpriv'].includes(base)&&s.school)return 'Заявление рассматривается · осталось '+Math.max(1,s.school.due-now())+' мес.';return '';}
function record(id){const s=state(),base=id.split('@')[0],g=group(base);if(g)s.last[g]=now();if(trips.has(base)){if(isWorking())s.leave=Math.max(0,s.leave-(base==='trip'?6:10));s.tripUntil=now()+1;}if(base==='meet'){s.meet=s.meet.filter(m=>now()-m<3);s.meet.push(now());}}
let originalSchool={};
function observe(){const s=state(),month=now(),elapsed=Math.max(0,month-s.at);if(elapsed&&isWorking())s.leave=Math.min(24,s.leave+elapsed);s.at=month;if(S.phase!=='life')return;if(s.school&&month>=s.school.due){const a=s.school;s.school=null;const all=S.fam.kids,targets=all.filter(k=>homeOthers().kids.includes(k)&&k.alive&&a.children.includes(childKey(k))&&S.age-k.bornAt>=6&&S.age-k.bornAt<18);if(targets.length){try{S.fam.kids=targets;originalSchool[a.kind]();}finally{S.fam.kids=all;}log('Рассмотрение заявления завершено: '+(a.kind==='kidpriv'?'детей перевели в частную школу.':'детей перевели в государственную школу.'),'warm');}else log('Перевод в школу не состоялся: дети уже не подходят по возрасту или больше не живут с вами.','note');}if(s.autoParents&&month>=s.nextParents){s.nextParents=month+12;const item=SHOP.find(i=>i.id==='parents'),cost=item.cost();if(item.ok()&&S.job!=='prison'&&S.money>=cost){S.money-=cost;book('Ежегодная помощь родителям',-cost);item.run();log('По вашей договорённости родителям перечислена ежегодная помощь: '+wonStr(cost)+'. Отношения +5 · Счастье +2.','warm');}else log('Ежегодная помощь родителям пропущена: '+(!parentAlive()?'нет живых родителей.':S.money<cost?'недостаточно доступных денег.':'сейчас перевод недоступен.'),'note');}}
function childKey(k){return String(k.name?.full||k.name)+'|'+k.bornAt;}
function autoParents(enabled){if(S.age<20||!parentAlive())throw Error('Регулярная помощь пока недоступна');const s=state();s.autoParents=!!enabled;s.nextParents=enabled?now()+12:null;log(enabled?'Вы включили ежегодную помощь родителям. Отдельные просьбы родственников по-прежнему требуют вашего решения.':'Вы отключили ежегодную помощь родителям.','note');}
function summary(){const s=state();return {autoParents:s.autoParents,parentCost:LifelineEconomy.toUSD(SHOP.find(i=>i.id==='parents').cost()),canParents:S.age>=20&&parentAlive(),nextParents:s.autoParents?Math.max(0,s.nextParents-now()):null,course:stage(),leave:Math.floor(s.leave)};}
function install(){for(const item of SHOP){if(group(item.id)||trips.has(item.id)||['meet','course','parents','kidpub','kidpriv'].includes(item.id))item.cd=0;if(['kidpub','kidpriv'].includes(item.id)){originalSchool[item.id]=item.run;item.run=function(){const s=state();s.school={kind:item.id,due:now()+3,children:S.fam.kids.filter(k=>k.alive&&S.age-k.bornAt>=6&&S.age-k.bornAt<18).map(childKey)};return 'Вы подали заявление о переводе детей. Рассмотрение займёт 3 месяца; до решения дети учатся в прежней школе.';};}}
const meeting=SHOP.find(i=>i.id==='meet'),meetOK=meeting.ok,meetRun=meeting.run;meeting.ok=function(){const at=S.flags.meetAt;try{S.flags.meetAt=null;return meetOK();}finally{S.flags.meetAt=at;}};meeting.d='Поиск знакомства сейчас · после четырёх попыток подряд понадобится перерыв';meeting.run=function(kind){if(kind==='match')return meetRun(kind);S.flags.meetAt=null;S.flags.meetK=null;if(chance(.55)){const p={meet:1,k:kind==='meet'?null:kind};S.pending={id:'partner',p,view:DEC.partner.build(p)};return 'Вы познакомились с новым человеком. Решите, хотите ли продолжить общение.';}return 'Сегодня подходящего знакомства не случилось. Можно попробовать другой способ.';};
const doCourse=courseDo;courseDo=function(...args){const st=stage();if(st.level>=5)return;const result=doCourse.apply(this,args);state().levels[st.key]=st.level+1;return result;};const autoCourse=courseAutoYear;courseAutoYear=function(...args){if(stage().level>=5)return;return autoCourse.apply(this,args);};
const buy=buyShop;buyShop=function(id,...args){observe();const why=reason(id);if(why)throw Error(why);const result=buy.call(this,id,...args);if(result)record(id);return result;};
const items=shopItems;shopItems=function(...args){const rows=items.apply(this,args);for(const row of rows){if(row.opts)for(const o of row.opts){const why=reason(o.id);if(why){o.avail=false;o.why=why;}}const why=reason(row.id);if(why){row.avail=false;row.why=why;if(row.opts)row.opts.forEach(o=>{o.avail=false;o.why=why;});}if(row.id==='course'){const st=stage();row.d='Ступень '+Math.min(5,st.level+1)+' из 5 · '+st.title+' · для каждой специальности отдельно';if(row.opts){const c=row.opts.find(o=>o.id==='course@c');if(c){c.n=st.title+' · '+Math.min(5,st.level+1)+'/5';if(st.level>=5){c.avail=false;c.why=reason(c.id);}}row.avail=row.opts.some(o=>o.avail);if(st.level>=5&&row.opts.some(o=>o.avail))row.why='';}}}return rows;};
}
root.LifelineSchedules={now,state,stage,reason,record,observe,autoParents,summary,install};
})(self);
